package com.enterprise.mm.erp.warehouse.outbound;

import com.enterprise.mm.common.*;
import com.enterprise.mm.error.*;
import com.enterprise.mm.warehouse.posting.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

/** Atomic source journal and 1C-initiated transport. No HTTP delivery inside business transactions. */
@Service
public class WarehouseOutboundService {
    private static final int NATIVE_PAYLOAD_MAX_UTF8_BYTES=8_000_000;
    private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final WarehouseOutboundSettings settings;private final WarehouseOutboundSources sources;
    public WarehouseOutboundService(JdbcTemplate jdbc,ObjectMapper mapper,WarehouseOutboundSettings settings){this.jdbc=jdbc;this.mapper=mapper.copy().enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);this.settings=settings;this.sources=new WarehouseOutboundSources(jdbc,this.mapper);}
    private String tenant(){String t=TenantContext.currentTenant();if(t==null||t.isBlank())throw new BadRequestException("Tenant scope required");return t;}
    private UUID company(){UUID c=CompanyContext.currentCompany();if(c==null)throw new BadRequestException("Company scope required");return c;}
    private void lock(){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(cast(? as text)||':'||cast(? as text)||':warehouse-outbound',0))",Object.class,tenant(),company());}
    private Map<String,Object> skipped(){return Map.of("skipped",true,"reason","OUTBOUND_DISABLED_OR_OUTSIDE_PINNED_SCOPE");}
    public boolean captureEnabled(){return settings.captureEnabled();}

    @Transactional(propagation=Propagation.MANDATORY)
    public Map<String,Object> captureStockMovement(UUID id){if(!settings.captureEnabled())return skipped();lock();return save(sources.movement(id),null);}
    @Transactional(propagation=Propagation.MANDATORY)
    public Map<String,Object> capturePosting(PostingCommand command,PostingReceipt receipt){if(!settings.captureEnabled())return skipped();lock();ObjectNode supplement=mapper.createObjectNode();supplement.put("book",command.book()).put("operation",command.operation()).put("contextKey",command.contextKey()).put("resourceId",command.resourceId().toString()).put("postingDate",command.postingDate().toString()).put("expectedVersion",command.expectedVersion()).put("idempotencyKey",command.idempotencyKey());supplement.set("payload",command.payload());return save(sources.posting(receipt.batchId()),supplement);}
    @Transactional(propagation=Propagation.MANDATORY)
    public Map<String,Object> captureHolding(UUID id){if(!settings.captureEnabled())return skipped();lock();return save(sources.holding(id),null);}
    @Transactional(propagation=Propagation.MANDATORY)
    public Map<String,Object> captureTransitLoss(UUID id){if(!settings.captureEnabled())return skipped();lock();return save(sources.transit(id),null);}

    private Map<String,Object> save(WarehouseOutboundSources.Evidence e,JsonNode command){
        if(e==null)return Map.of("skipped",true,"reason","SOURCE_ALREADY_OWNED_BY_NATIVE_1C_OR_OPENING");
        ObjectNode source=mapper.createObjectNode();source.put("sourceKey",e.key()).put("sourceEngine",e.engine()).put("operationType",e.operation()).put("resourceId",e.resource().toString()).put("postingDate",e.date().toString());source.set("facts",e.facts());source.set("rawEffects",e.raw());String sourceHash=hash(canonical(source).toString());
        var existing=jdbc.queryForList("select * from one_c_warehouse_outbound where tenant_id=? and company_id=? and source_key=? for update",tenant(),company(),e.key());
        if(!existing.isEmpty())settings.validate(String.valueOf(existing.getFirst().get("source_instance_id")),String.valueOf(existing.getFirst().get("organization_id")));UUID id=existing.isEmpty()?UUID.nameUUIDFromBytes((tenant()+":"+company()+":"+e.key()).getBytes(StandardCharsets.UTF_8)):(UUID)existing.getFirst().get("operation_id");long revision=existing.isEmpty()?1:((Number)existing.getFirst().get("revision")).longValue()+1;
        if(!existing.isEmpty()&&sourceHash.equals(existing.getFirst().get("source_hash")))return Map.of("operationId",id,"revision",revision-1,"replayed",true);
        if(!existing.isEmpty()&&!e.revisioned())throw new ConflictException("Immutable warehouse source evidence changed: "+e.key());
        String policy=e.registryOnly()?"REGISTRY_ONLY":"NATIVE_MAPPING_REQUIRED";
        if(existing.isEmpty())jdbc.update("insert into one_c_warehouse_outbound(operation_id,tenant_id,company_id,source_instance_id,organization_id,source_key,source_engine,source_hash,operation_type,resource_id,posting_date,revision,policy,eligible_context,pending_reason,legacy_candidates) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,cast(? as jsonb))",id,tenant(),company(),settings.instance(),settings.organization(),e.key(),e.engine(),sourceHash,e.operation(),e.resource(),java.sql.Date.valueOf(e.date()),revision,policy,e.eligible(),e.reason(),mapper.valueToTree(e.candidates()).toString());
        else{jdbc.update("update one_c_warehouse_outbound_versions set state='SUPERSEDED' where operation_id=? and revision=? and result_json is null",id,revision-1);jdbc.update("update one_c_warehouse_outbound set source_hash=?,revision=?,policy=?,state='PENDING',pending_reason=?,lease_token=null,lease_worker=null,lease_until=null,native_document_id=null,updated_at=current_timestamp where operation_id=?",sourceHash,revision,policy,e.reason(),id);}
        UUID event=UUID.randomUUID();ObjectNode payload=source.deepCopy();payload.put("protocolVersion",2).put("sourceInstanceId",settings.instance()).put("organizationId",settings.organization()).put("operationId",id.toString()).put("eventId",event.toString()).put("revision",revision).put("policy",policy);if(e.eligible()==null)payload.putNull("contextName");else payload.put("contextName",e.eligible());if(command!=null){((ObjectNode)payload.path("rawEffects")).set("commandContext",command);((ObjectNode)payload.path("rawEffects")).put("commandPayloadAvailable",true);}insertVersion(id,revision,event,payload,null,null);return Map.of("operationId",id,"revision",revision,"replayed",false);
    }
    private void insertVersion(UUID id,long revision,UUID event,JsonNode payload,String approvalKey,String approvalHash){String json=canonical(payload).toString();String actor=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getName();jdbc.update("insert into one_c_warehouse_outbound_versions(operation_id,revision,event_id,payload_json,payload_hash,approval_key,approval_hash,approved_by) values(?,?,?,?,?,?,?,?)",id,revision,event,json,hash(json),approvalKey,approvalHash,approvalKey==null?null:actor);}
    private Map<String,Object> head(UUID id){var rows=jdbc.queryForList("select * from one_c_warehouse_outbound where operation_id=? and tenant_id=? and company_id=? for update",id,tenant(),company());if(rows.isEmpty())throw new NotFoundException("Warehouse outbound operation not found");return rows.getFirst();}
    private Map<String,Object> version(UUID id,long revision){var rows=jdbc.queryForList("select * from one_c_warehouse_outbound_versions where operation_id=? and revision=?",id,revision);if(rows.isEmpty())throw new NotFoundException("Warehouse outbound revision not found");return rows.getFirst();}
    private long rev(Map<String,Object> head){return ((Number)head.get("revision")).longValue();}
    private JsonNode payload(Map<String,Object> version){return parse(String.valueOf(version.get("payload_json")));}

    @Transactional
    public Map<String,Object> poll(JsonNode request){nativeScope(request);if(!request.path("limit").isIntegralNumber()||request.path("limit").asInt()!=1)throw new BadRequestException("Native operation poll limit must be 1");String worker=text(request,"workerId",160);lock();
        var rows=jdbc.queryForList("select operation_id from one_c_warehouse_outbound where tenant_id=? and company_id=? and source_instance_id=? and organization_id=? and (state='PENDING' or (state='LEASED' and lease_until<current_timestamp)) order by created_at,operation_id for update skip locked limit 1",tenant(),company(),settings.instance(),settings.organization());if(rows.isEmpty())return Map.of("operations",List.of());UUID id=(UUID)rows.getFirst().get("operation_id");Map<String,Object> h=head(id);long revision=rev(h);var v=version(id,revision);
        boolean legacy=legacyEligible(h)&&Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from erp_exchange_envelope e where e.tenant_id=? and e.company_id=? and e.document_id in(select value::uuid from jsonb_array_elements_text(cast(? as jsonb))) and e.operation is not null)",Boolean.class,tenant(),company(),String.valueOf(h.get("legacy_candidates"))));
        if(legacy&&!"LEGACY_LINKED".equals(h.get("policy"))){ObjectNode linked=payload(v).deepCopy();revision++;UUID event=UUID.randomUUID();linked.put("revision",revision).put("eventId",event.toString()).put("policy","LEGACY_LINKED");jdbc.update("update one_c_warehouse_outbound_versions set state='SUPERSEDED' where operation_id=? and revision=?",id,revision-1);jdbc.update("update one_c_warehouse_outbound set revision=?,policy='LEGACY_LINKED',pending_reason='LEGACY_V1_OWNS_NATIVE_POSTING' where operation_id=?",revision,id);insertVersion(id,revision,event,linked,null,null);v=version(id,revision);}
        if(!nativePayloadFits(String.valueOf(v.get("payload_json")))){
            jdbc.update("update one_c_warehouse_outbound set state='REVIEW_REQUIRED',pending_reason='SOURCE_PAYLOAD_EXCEEDS_NATIVE_LIMIT',lease_token=null,lease_worker=null,lease_until=null,updated_at=current_timestamp where operation_id=?",id);
            jdbc.update("update one_c_warehouse_outbound_versions set state='REVIEW_REQUIRED' where operation_id=? and revision=?",id,revision);
            return Map.of("operations",List.of());
        }
        UUID token=UUID.randomUUID();jdbc.update("update one_c_warehouse_outbound set state='LEASED',lease_token=?,lease_worker=?,lease_until=current_timestamp+interval '120 seconds',attempts=attempts+1,updated_at=current_timestamp where operation_id=?",token,worker,id);jdbc.update("update one_c_warehouse_outbound_versions set state='LEASED' where operation_id=? and revision=?",id,revision);
        return Map.of("operations",List.of(Map.of("operationId",id,"eventId",v.get("event_id"),"revision",revision,"leaseToken",token,"payloadJson",v.get("payload_json"),"payloadHash",v.get("payload_hash"))));
    }
    @Transactional
    public Map<String,Object> result(UUID id,JsonNode request){nativeScope(request);String worker=text(request,"workerId",160),hash=text(request,"payloadHash",64);long revision=positiveRevision(request,"revision");UUID token=uuid(request,"leaseToken");String status=text(request,"status",24);if(!Set.of("OBSERVED","REVIEW_REQUIRED","APPLIED","FAILED").contains(status))throw new BadRequestException("Invalid native operation result status");lock();var h=head(id);settings.validate(String.valueOf(h.get("source_instance_id")),String.valueOf(h.get("organization_id")));var v=version(id,revision);String resultHash=hash(canonical(request).toString());
        if(v.get("result_json")!=null){if(!resultHash.equals(v.get("result_hash")))throw new ConflictException("Native result already has different immutable contents");return Map.of("operationId",id,"revision",revision,"status",v.get("state"),"replayed",true);}
        if(revision!=rev(h)||!"LEASED".equals(h.get("state"))||!worker.equals(h.get("lease_worker"))||!token.equals(h.get("lease_token"))||!hash.equals(v.get("payload_hash"))||!Boolean.TRUE.equals(jdbc.queryForObject("select lease_until>=current_timestamp from one_c_warehouse_outbound where operation_id=?",Boolean.class,id)))throw new ConflictException("Native result lease, revision, worker or payload fence differs");
        UUID nativeId=request.hasNonNull("nativeDocumentId")&&!request.path("nativeDocumentId").asText().isBlank()?uuid(request,"nativeDocumentId"):null;
        if("APPLIED".equals(status)&&(!"NATIVE_CORRECTION".equals(h.get("policy"))||nativeId==null||nativeId.equals(new UUID(0,0))))throw new ConflictException("Applied native proof requires an approved correction and nonzero native document");
        if("OBSERVED".equals(status)&&!Set.of("LEGACY_LINKED","REGISTRY_ONLY").contains(String.valueOf(h.get("policy"))))throw new ConflictException("Unmapped native operations require explicit review");
        String message=optional(request,"message",4000);jdbc.update("update one_c_warehouse_outbound_versions set state=?,result_json=?,result_hash=?,result_at=current_timestamp where operation_id=? and revision=?",status,canonical(request).toString(),resultHash,id,revision);jdbc.update("update one_c_warehouse_outbound set state=?,native_document_id=?,pending_reason=?,lease_until=null,updated_at=current_timestamp where operation_id=?",status,nativeId,message==null?status:message,id);return Map.of("operationId",id,"revision",revision,"status",status,"replayed",false);
    }
    private void nativeScope(JsonNode n){if(n==null||!n.path("protocolVersion").isIntegralNumber()||n.path("protocolVersion").asInt()!=2)throw new BadRequestException("Warehouse protocolVersion 2 required");settings.validate(text(n,"sourceInstanceId",160),text(n,"organizationId",160));}
    private boolean legacyEligible(Map<String,Object> head){
        String engine=String.valueOf(head.get("source_engine")),type=String.valueOf(head.get("operation_type")).toUpperCase(Locale.ROOT);
        if(!Set.of("STOCK_MOVEMENT","POSTING_BATCH").contains(engine))return false;
        if(type.startsWith("TRANSFER_"))return type.startsWith("TRANSFER_DISPATCH:")||type.startsWith("TRANSFER_GOOD_RECEIPT:")||type.startsWith("TRANSFER_QUARANTINE_RETURN_DISPATCH:");
        if(List.of("PRODUCTION","PROCESSOR","TRANSFORM","CUTTING","ASSEMBLY","DISASSEMBLY","RETURN","CUSTODY","INSTALLATION","HOLDING","PACKAG","WRITE_OFF","ADJUSTMENT","REVERSAL").stream().anyMatch(type::contains))return false;
        return type.equals("RECEIPT")||type.equals("ISSUE")||type.endsWith(":RECEIPT")||type.endsWith(":ISSUE");
    }

    @Transactional
    public Map<String,Object> approve(UUID id,JsonNode request,String key){settings.requireEnabled();lock();if(key==null||key.isBlank()||key.length()>160)throw new BadRequestException("Approval Idempotency-Key required");var h=head(id);settings.validate(String.valueOf(h.get("source_instance_id")),String.valueOf(h.get("organization_id")));String fingerprint=hash(canonical(request).toString());var replay=jdbc.queryForList("select revision,approval_hash from one_c_warehouse_outbound_versions where operation_id=? and approval_key=?",id,key);if(!replay.isEmpty()){if(!fingerprint.equals(replay.getFirst().get("approval_hash")))throw new ConflictException("Approval key already used with different command");return Map.of("operationId",id,"revision",replay.getFirst().get("revision"),"replayed",true);}
        if(positiveRevision(request,"expectedRevision")!=rev(h)||"APPLIED".equals(h.get("state"))||"LEASED".equals(h.get("state"))||"LEGACY_LINKED".equals(h.get("policy"))||h.get("eligible_context")==null)throw new ConflictException("Source context, revision or native ownership does not allow correction approval");
        var v=version(id,rev(h));if(!nativePayloadFits(String.valueOf(v.get("payload_json"))))throw new BadRequestException("Source payload exceeds native limit; a dedicated transport is required");ObjectNode next=payload(v).deepCopy();JsonNode command=request.path("nativeCommand");validateCommand(command,next.path("facts"),String.valueOf(h.get("eligible_context")));long revision=rev(h)+1;UUID event=UUID.randomUUID();next.put("revision",revision).put("eventId",event.toString()).put("policy","NATIVE_CORRECTION");next.set("nativeCommand",command.deepCopy());if(!nativePayloadFits(canonical(next).toString()))throw new BadRequestException("Approved packet exceeds native limit");jdbc.update("update one_c_warehouse_outbound_versions set state='SUPERSEDED' where operation_id=? and revision=? and result_json is null",id,rev(h));jdbc.update("update one_c_warehouse_outbound set revision=?,policy='NATIVE_CORRECTION',state='PENDING',pending_reason='NATIVE_CORRECTION_AWAITING_DELIVERY',lease_token=null,lease_worker=null,lease_until=null,updated_at=current_timestamp where operation_id=?",revision,id);insertVersion(id,revision,event,next,key,fingerprint);return Map.of("operationId",id,"revision",revision,"replayed",false);
    }
    private void validateCommand(JsonNode command,JsonNode facts,String context){
        if(!command.isObject()||!"Документ.КоррекцияНоменклатуры".equals(command.path("documentType").asText())||!context.equals(command.path("context").asText())||!settings.organization().equals(command.path("organizationId").asText())||!command.path("rows").isArray()||command.path("rows").isEmpty()||command.path("rows").size()!=facts.size())throw new BadRequestException("Native command must match the generated correction context, organization and full fact set");
        List<String> expected=new ArrayList<>(),actual=new ArrayList<>();for(JsonNode f:facts){if(!"STOCK".equals(f.path("domain").asText())||!"UZS".equals(f.path("currency").asText())||f.hasNonNull("ownerId")||f.hasNonNull("stockCategory")&&!"OWNED".equals(f.path("stockCategory").asText()))throw new BadRequestException("Nonowned or transit facts require a dedicated native adapter");expected.add(proof(f,"materialId","warehouseId"));}
        for(JsonNode r:command.path("rows")){for(String field:List.of("materialId","warehouseId","stockAccountId","contraAccountId","mmMaterialId","mmWarehouseId"))if(uuid(r,field).equals(new UUID(0,0)))throw new BadRequestException("Native mapping references must be nonzero");if(!settings.allowsContra(uuid(r,"contraAccountId").toString()))throw new BadRequestException("Native contra account is not explicitly allowed");if(!"STOCK".equals(r.path("domain").asText()))throw new BadRequestException("Native correction domain must match stock");actual.add(proof(r,"mmMaterialId","mmWarehouseId"));if(!r.path("contraAnalytics").isArray()||r.path("contraAnalytics").size()>10)throw new BadRequestException("Explicit contra analytics descriptors required");var indices=new HashSet<Integer>();for(JsonNode a:r.path("contraAnalytics")){if(!a.path("index").isIntegralNumber()||a.path("index").asInt()<1||a.path("index").asInt()>10||!indices.add(a.path("index").asInt()))throw new BadRequestException("Invalid contra analytic index");if(a.hasNonNull("catalog")){text(a,"catalog",100);uuid(a,"id");}else if(!Set.of("String","Number").contains(a.path("type").asText())||!a.hasNonNull("value"))throw new BadRequestException("Invalid contra analytic descriptor");}}
        Collections.sort(expected);Collections.sort(actual);if(!expected.equals(actual))throw new BadRequestException("Native mapped quantities or values differ from exact source stock facts");
    }
    private String proof(JsonNode n,String material,String warehouse){return text(n,"domain",20)+"|"+uuid(n,material)+"|"+uuid(n,warehouse)+"|"+decimal(n,"quantity").stripTrailingZeros().toPlainString()+"|"+decimal(n,"amount").stripTrailingZeros().toPlainString();}

    @Transactional
    public Map<String,Object> reconcile(JsonNode request){settings.requireEnabled();lock();String cursor=request.path("cursor").asText("");if(cursor.length()>300)throw new BadRequestException("Invalid source cursor");int limit=request.path("limit").asInt(100);if(limit<1||limit>200)throw new BadRequestException("Reconciliation limit must be 1..200");
        var rows=jdbc.queryForList("""
            select * from (
             select 'STOCK_MOVEMENT:'||id as source_key,id,'STOCK_MOVEMENT' as engine from stock_movements where tenant_id=? and company_id=? and posted_at is not null and coalesce(reference_type,'') not in('ONE_C_API','OPENING_STOCK_EXACT','OPENING_STOCK','TRANSFER_TRANSIT_LOSS')
             union all select 'POSTING_BATCH:'||id,id,'POSTING_BATCH' from warehouse_posting_batches where tenant_id=? and company_id=? and status='COMMITTED'
             union all select 'HOLDING:'||id,id,'HOLDING' from warehouse_holdings where tenant_id=? and company_id=?
             union all select 'TRANSIT_LOSS:'||id,id,'TRANSIT_LOSS' from stock_movements where tenant_id=? and company_id=? and posted_at is not null and reference_type='TRANSFER_TRANSIT_LOSS'
            ) sources where source_key>? order by source_key limit ?
            """,tenant(),company(),tenant(),company(),tenant(),company(),tenant(),company(),cursor,limit+1);
        boolean complete=rows.size()<=limit;int count=Math.min(rows.size(),limit),captured=0;String next=cursor;for(int i=0;i<count;i++){var row=rows.get(i);UUID id=(UUID)row.get("id");WarehouseOutboundSources.Evidence source=switch(row.get("engine").toString()){case "STOCK_MOVEMENT"->sources.movement(id);case "POSTING_BATCH"->sources.posting(id);case "HOLDING"->sources.holding(id);case "TRANSIT_LOSS"->sources.transit(id);default->throw new IllegalStateException();};var result=save(source,null);if(Boolean.FALSE.equals(result.get("replayed")))captured++;next=String.valueOf(row.get("source_key"));}return Map.of("cursor",cursor,"nextCursor",next,"scanned",count,"captured",captured,"complete",complete,"operationalApplication","PRESERVE_MM_NATIVE");
    }
    private static final String HEAD="operation_id as id,operation_id as \"operationId\",revision,source_key as \"sourceKey\",source_engine as \"sourceEngine\",operation_type as \"operationType\",resource_id as \"resourceId\",posting_date as \"postingDate\",policy,state,pending_reason as \"pendingReason\",eligible_context as \"eligibleContext\",native_document_id as \"nativeDocumentId\",lease_until as \"leaseUntil\",attempts,created_at as \"createdAt\",updated_at as \"updatedAt\"";
    @Transactional(readOnly=true) public List<Map<String,Object>> list(int limit,int offset){return jdbc.queryForList("select "+HEAD+" from one_c_warehouse_outbound where tenant_id=? and company_id=? order by created_at desc,operation_id limit ? offset ?",tenant(),company(),Math.max(1,Math.min(limit,200)),Math.max(offset,0));}
    @Transactional(readOnly=true) public Map<String,Object> detail(UUID id){var h=jdbc.queryForList("select "+HEAD+" from one_c_warehouse_outbound where tenant_id=? and company_id=? and operation_id=?",tenant(),company(),id);if(h.isEmpty())throw new NotFoundException("Warehouse outbound operation not found");var versions=jdbc.queryForList("select revision,event_id as \"eventId\",payload_hash as \"payloadHash\",payload_json as \"payloadJson\",state,result_json as result,approved_by as \"approvedBy\",created_at as \"createdAt\",result_at as \"resultAt\" from one_c_warehouse_outbound_versions where operation_id=? order by revision desc",id);for(var v:versions)if(v.get("result")!=null)v.put("result",parse(String.valueOf(v.get("result"))));return Map.of("operation",h.getFirst(),"versions",versions,"operationalApplication","PRESERVE_MM_NATIVE");}
    @Transactional(readOnly=true) public Map<String,Object> coverage(){var out=new LinkedHashMap<String,Object>(settings.config());out.put("total",count(null));for(var pair:Map.of("pending","PENDING","leased","LEASED","observed","OBSERVED","reviewRequired","REVIEW_REQUIRED","applied","APPLIED","failed","FAILED").entrySet())out.put(pair.getKey(),count(pair.getValue()));out.put("byPolicy",jdbc.queryForList("select policy,count(*) as count from one_c_warehouse_outbound where tenant_id=? and company_id=? group by policy order by policy",tenant(),company()));out.put("byEngine",jdbc.queryForList("select source_engine as \"sourceEngine\",count(*) as count from one_c_warehouse_outbound where tenant_id=? and company_id=? group by source_engine order by source_engine",tenant(),company()));return out;}
    private long count(String state){return jdbc.queryForObject("select count(*) from one_c_warehouse_outbound where tenant_id=? and company_id=? and (cast(? as text) is null or state=?)",Long.class,tenant(),company(),state,state);}
    private JsonNode canonical(JsonNode n){if(n.isObject()){ObjectNode out=mapper.createObjectNode();var keys=new TreeSet<String>();n.fieldNames().forEachRemaining(keys::add);for(String k:keys)out.set(k,canonical(n.get(k)));return out;}if(n.isArray()){ArrayNode out=mapper.createArrayNode();for(JsonNode v:n)out.add(canonical(v));return out;}return n;}
    private String hash(String json){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private boolean nativePayloadFits(String json){return json.getBytes(StandardCharsets.UTF_8).length<=NATIVE_PAYLOAD_MAX_UTF8_BYTES;}
    private JsonNode parse(String json){try{return mapper.readTree(json);}catch(Exception e){throw new IllegalStateException(e);}}
    private String text(JsonNode n,String field,int max){if(!n.path(field).isTextual()||n.path(field).asText().isBlank()||n.path(field).asText().length()>max)throw new BadRequestException("Invalid "+field);return n.path(field).asText();}
    private String optional(JsonNode n,String field,int max){if(!n.hasNonNull(field))return null;if(!n.path(field).isTextual()||n.path(field).asText().length()>max)throw new BadRequestException("Invalid "+field);return n.path(field).asText();}
    private UUID uuid(JsonNode n,String field){try{return UUID.fromString(text(n,field,36));}catch(RuntimeException e){throw new BadRequestException("Invalid "+field);}}
    private long positiveRevision(JsonNode n,String field){if(!n.path(field).isIntegralNumber()||!n.path(field).canConvertToLong()||n.path(field).asLong()<1)throw new BadRequestException("Invalid "+field);return n.path(field).asLong();}
    private BigDecimal decimal(JsonNode n,String field){String value=text(n,field,80);if(!value.matches("-?[0-9]{1,30}(\\.[0-9]{1,20})?"))throw new BadRequestException("Exact decimal string required: "+field);return new BigDecimal(value);}
}
